namespace Kentico.Xperience.ContentItemVersionCompare;

/// <summary>
/// Settings of the Version comparison module. Registration is optional - the defaults work without
/// any configuration. To change them, configure the options during application start-up:
/// <code>
/// builder.Services.Configure&lt;VersionComparisonOptions&gt;(options =&gt;
/// {
///     options.ThumbnailVariantName = "Thumbnail";
/// });
/// </code>
/// </summary>
public class VersionComparisonOptions
{
    /// <summary>
    /// Name of the image variant used for thumbnails, as generated by the project's image
    /// processing configuration. Set to <see langword="null"/> to link the original file instead,
    /// which always exists but downloads the full-size image.
    /// </summary>
    /// <remarks>
    /// A variant that the project does not generate results in a broken thumbnail, so change this
    /// to match the variants your project produces.
    /// </remarks>
    public string ThumbnailVariantName { get; set; } = "Small";

    /// <summary>
    /// Upper bound on the number of words compared per side, applied to the part of a field that
    /// actually differs.
    /// </summary>
    /// <remarks>
    /// Matching text at the start and the end of a value is set aside before the comparison runs,
    /// so this limit applies to the edited region rather than to the whole field. The comparison
    /// allocates a table of older x newer words, so the cost grows with the square of this value.
    /// A field whose edited region exceeds it is shown without inline highlighting.
    /// </remarks>
    public int MaxDiffTokens { get; set; } = 800;
}
